-- (c) 2024-2026 Gary Christmas / Selah Now LLC.
-- S6 . The class the first corpus did not have.
--
-- REQUIRES S1 and S3. Adds a SECOND corpus alongside the first rather than
-- replacing it, so the old scores stay comparable.
--
-- ---------------------------------------------------------------------------
-- WHAT THE MEASUREMENT FOUND, AND WHY THIS EXISTS
--
--   S5 scored the ranking at 31.7% precision at one, against 36.1% for a coin
--   toss. Worse than chance. Tracing it: ZERO of 30 planted chains ranked
--   first, because every one of them starts from a need that ALSO has a plain
--   direct answer -- the chain's own first link. A ranker that prefers the
--   short route put the direct candidate first, which is correct advice, and
--   the answer key called it wrong 30 times.
--
--   So the corpus could not measure chain ranking at all. A chain was never
--   actually the better answer in it.
--
-- WHAT MAKES A CHAIN THE ONLY ROUTE
--
--   An offer that cannot be taken up until its owner's own need is met.
--   `blocked_on` carries that: the one member who can help A is unavailable
--   until C helps B. Proposing the A/B pair on its own is then proposing
--   something that cannot happen, and the chain is not a nicer route, it is
--   the route.
--
--   That is the case multi-hop exists for, and nothing was testing it.
--
-- AND TIMEZONES
--   Zero of 400 members in the first corpus had one. Cross-border ranking had
--   language and nothing else, and language separated a need's foreign
--   candidates barely more than one way out of two. A corpus that withholds
--   the deciding signal cannot test a decision.

BEGIN;

-- An offer nobody can take up yet. Null means available now, which is almost
-- all of them.
ALTER TABLE sim.offers ADD COLUMN IF NOT EXISTS blocked_on uuid REFERENCES sim.needs(sim_need_id);

COMMENT ON COLUMN sim.offers.blocked_on IS
  'The owner''s own need that must be met before this offer can be taken up. When set, any suggestion proposing this offer on its own is proposing something that cannot happen.';

-- The answer key gains a kind.
--
-- FOUND BY NAME, NOT BY GUESS. The first version dropped
-- `sim_planted_kind_check`, which does not exist: Postgres named the
-- constraint `planted_kind_check` when S1 created it inline. DROP ... IF
-- EXISTS then did nothing at all, silently, and the first insert of the new
-- kind failed against a constraint I believed I had removed. Same lesson as
-- CREATE TABLE IF NOT EXISTS: a statement that quietly does nothing is worse
-- than one that fails.
DO $$
DECLARE cname text;
BEGIN
  SELECT con.conname INTO cname
    FROM pg_constraint con
    JOIN pg_class rel ON rel.oid = con.conrelid
    JOIN pg_namespace ns ON ns.oid = rel.relnamespace
   WHERE ns.nspname = 'sim' AND rel.relname = 'planted'
     AND con.contype = 'c'
     AND pg_get_constraintdef(con.oid) LIKE '%unanswerable%';
  IF cname IS NULL THEN
    RAISE EXCEPTION 'the kind constraint on sim.planted was not found -- S1 may not have run';
  END IF;
  EXECUTE format('ALTER TABLE sim.planted DROP CONSTRAINT %I', cname);
END $$;

ALTER TABLE sim.planted ADD CONSTRAINT planted_kind_check CHECK (kind IN (
  'direct', 'cross_border', 'hop2', 'hop3', 'pool', 'unanswerable',
  'chain_only'));


COMMIT;


-- -- IS THE NEW ANSWER KEY TRUE? ---------------------------------------------
SELECT kind, plants, links, verdict FROM sim.v_plant_integrity
 WHERE run_id = (SELECT run_id FROM sim.runs WHERE label LIKE 'corpus-400b%')
 ORDER BY kind;

-- And is the chain really the only route? For every chain_only plant, the
-- single local offer answering the start need must be blocked. Zero is the
-- only acceptable answer; anything else means the class is not what it claims.
SELECT count(*) AS chain_only_plants,
       count(*) FILTER (WHERE o.blocked_on IS NULL) AS sole_offer_not_blocked
  FROM sim.planted p
  JOIN sim.needs  n ON n.sim_need_id = p.sim_need_id
  JOIN sim.offers o ON o.sim_offer_id = ((p.chain -> 0) ->> 'offer_id')::uuid
 WHERE p.kind = 'chain_only';
